}

.radio-option input[type="radio"]:focus + label {
    outline: 2px solid var(--color-primary-focus);
    outline-offset: 2px;
    border-color: var(--color-primary-focus);
}

.radio-option input[type="radio"]:focus:not(:focus-visible) + label {
    outline: none;
}

.radio-option input[type="radio"]:disabled + label {
    opacity: 0.6;
    cursor: not-allowed;
    background-color: var(--color-background-light);
}

.radio-label-text {
    display: block;
    font-weight: var(--font-weight-semibold);
    color: var(--color-text-primary);
}

.radio-label-description {
    display: block;
    font-size: var(--font-size-sm);
    color: var(--color-text-secondary);
    margin-top: var(--spacing-xs);
}

/* Form Actions */
.form-actions {
    display: flex;
    gap: var(--spacing-md);
    margin-top: var(--spacing-2xl);
}

.submit-button {
    flex: 1;
    padding: var(--spacing-md) var(--spacing-lg);
    background-color: var(--color-primary);
    color: white;
    font-size: var(--font-size-base);
    font-weight: var(--font-weight-semibold);
    border: none;
    border-radius: var(--radius-md);
    cursor: pointer;
    transition: all var(--transition-base);
}

.submit-button:hover {
    background-color: var(--color-primary-hover);
    box-shadow: 0 4px 6px 0 rgba(37, 99, 235, 0.3);
}

.submit-button:active {
    background-color: var(--color-primary-focus);
}

.submit-button:focus {
    outline: 2px solid var(--color-primary-focus);
    outline-offset: 2px;
}

.submit-button:focus:not(:focus-visible) {
    outline: none;
}

.submit-button:disabled {
    background-color: var(--color-border);
    color: var(--color-text-secondary);
    cursor: not-allowed;
}

